            const resolved = resolveTarget(scope, spec, isFirstParty);
            if (!resolved)
                return;
            const messageId = violation(scope, resolved);
            if (!messageId)
                return;
            context.report({
                node,
                messageId,
                data: reportData(scope, messageId, resolved.target),
